-- Security & Access Governance 1.0.0 — consumer and agent grants
--
-- Every object is granted by name. GRANT ... ON ALL VIEWS would widen
-- the product silently the next time a view is added to the schema.
--
-- Consumers: ROLE_SECURITY_ANALYST, ROLE_AUDITOR
--
-- Generated by the Observability & FinOps Platform. Review before running.
-- The platform does not execute this script; a human does (R2, R8).

USE ROLE SECURITYADMIN;

GRANT USAGE ON DATABASE OBSERVABILITY TO ROLE SNOWOBS_CONSUMER;
GRANT USAGE ON SCHEMA OBSERVABILITY.PUBLISHED TO ROLE SNOWOBS_CONSUMER;
GRANT USAGE ON SCHEMA OBSERVABILITY.SEMANTIC TO ROLE SNOWOBS_CONSUMER;

GRANT SELECT ON VIEW OBSERVABILITY.PUBLISHED.V_ACCESS_GOVERNANCE_LOGIN TO ROLE SNOWOBS_CONSUMER;
GRANT SELECT ON VIEW OBSERVABILITY.PUBLISHED.V_ACCESS_GOVERNANCE_GRANT TO ROLE SNOWOBS_CONSUMER;
GRANT SELECT ON VIEW OBSERVABILITY.PUBLISHED.V_ACCESS_GOVERNANCE_USER TO ROLE SNOWOBS_CONSUMER;

GRANT REFERENCES ON SEMANTIC VIEW OBSERVABILITY.SEMANTIC.ACCESS_GOVERNANCE TO ROLE SNOWOBS_CONSUMER;
GRANT REFERENCES ON SEMANTIC VIEW OBSERVABILITY.SEMANTIC.ACCESS_GOVERNANCE TO ROLE SNOWOBS_AGENT_USER;

GRANT USAGE ON CORTEX SEARCH SERVICE OBSERVABILITY.SEARCH.ACCESS_GOVERNANCE_ERROR_CLASS TO ROLE SNOWOBS_AGENT_USER;
GRANT USAGE ON AGENT OBSERVABILITY.AGENT.ACCESS_GOVERNANCE_AGENT TO ROLE SNOWOBS_AGENT_USER;
GRANT USAGE ON WAREHOUSE WH_SNOWOBS_AGENT TO ROLE SNOWOBS_AGENT_USER;

-- Grant the consumer role onward to the registered consumers. Each line is
-- one entry in the product's consumer register; adding a consumer is a
-- registry change, not an ad-hoc grant.
GRANT ROLE SNOWOBS_CONSUMER TO ROLE ROLE_SECURITY_ANALYST;  -- Security engineering
GRANT ROLE SNOWOBS_CONSUMER TO ROLE ROLE_AUDITOR;  -- Internal audit

SHOW GRANTS TO ROLE SNOWOBS_CONSUMER;
